from typing import Protocol

class Closer(Protocol):
    def close(self) -> None: ...

def close_all(items: list[Closer]) -> int:
    for item in items:
        item.close()
    return len(items)

import io
print(close_all([io.StringIO(), io.BytesIO()]))  # 2: neither inherits Closer

