from typing import Literal, TypedDict

class Deposit(TypedDict):
    kind: Literal['deposit']
    amount: int

class Fee(TypedDict):
    kind: Literal['fee']
    amount: int
    reason: str

Event = Deposit | Fee

def balance(events: list[Event]) -> int:
    total = 0
    for event in events:
        if event['kind'] == 'deposit':
            total += event['amount']      # event: Deposit
        else:
            total -= event['amount']      # event: Fee
    return total

print(balance([{'kind': 'deposit', 'amount': 50},
               {'kind': 'fee', 'amount': 5, 'reason': 'atm'}]))  # 45

