solution:
Map each schema name to the runtime class (or tuple of classes) that `isinstance` should accept, and special-case bool because it subclasses int. For each schema field: a missing key is an error only if required; a None value is fine only if optional; otherwise compare against the class and report the actual `type(value).__name__`. A second pass over the record finds unexpected keys. Sorting at the end makes the output deterministic regardless of dict order. O(fields) time.

TYPES = {'int': int, 'float': (int, float), 'str': str,
         'bool': bool, 'list': list, 'dict': dict}


def type_name(value):
    return 'None' if value is None else type(value).__name__


def matches(value, name):
    if isinstance(value, bool):          # bool subclasses int: only 'bool' accepts it
        return name == 'bool'
    return isinstance(value, TYPES[name])


def validate(record: dict[str, object], schema: dict[str, str]) -> list[str]:
    errors: list[str] = []
    for field, spec in schema.items():
        name = spec.removesuffix('?')
        optional = spec.endswith('?')
        if field not in record:
            if not optional:
                errors.append(f'{field}: missing')
            continue
        value = record[field]
        if value is None and optional:
            continue
        if not matches(value, name):
            errors.append(f'{field}: expected {name}, got {type_name(value)}')
    errors.extend(f'{field}: unexpected' for field in record if field not in schema)
    return sorted(errors)

