import math


def shape_area(shape: dict) -> float | None:
    match shape:
        case {'kind': 'circle', 'r': r}:
            return math.pi * r * r
        case {'kind': 'rect', 'w': w, 'h': h}:
            return w * h
        case {'kind': 'square', 'side': side}:
            return side * side
        case _:
            return None


def total_area(shapes: list[dict]) -> dict[str, float]:
    total, unknown = 0, 0
    for shape in shapes:
        area = shape_area(shape)
        if area is None:
            unknown += 1
        else:
            total += area
    return {'area': round(total, 2), 'unknown': unknown}

from collections.abc import Callable, Hashable, Iterable
from operator import itemgetter


def latest[T, K: Hashable](items: Iterable[T], key: Callable[[T], K],
                           rank: Callable[[T], int]) -> list[T]:
    best: dict[K, T] = {}
    for item in items:
        k = key(item)
        if k not in best or rank(item) > rank(best[k]):
            best[k] = item
    return list(best.values())


def latest_by(records: list[dict], key_field: str, time_field: str) -> list[dict]:
    return latest(records, itemgetter(key_field), itemgetter(time_field))

